import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);
  assert.deepEqual(r.value.lines[0], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 5,
    unitPrice: 9500,
    vatRate: 21,
  });
  assert.deepEqual(r.value.lines[1], {
    sku: 'LOGO-PACK',
    name: 'Logo package',
    qty: 1,
    unitPrice: 120000,
    vatRate: 21,
  });
});

test('createInvoice rejects an unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects an invalid date format', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026/10/07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects an invalid date (nonexistent)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects an empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects undefined lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: undefined,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects a non-positive quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 0 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects a negative quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: -1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects a fractional quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1.5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects an unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  };
  const inputCopy = JSON.parse(JSON.stringify(input));
  createInvoice(input);
  assert.deepEqual(input, inputCopy);
});

test('createInvoice with multiple lines including various VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-01-01',
    lines: [
      { sku: 'COPY-HOUR', qty: 10 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 3);
  assert.equal(r.value.lines[0].vatRate, 21);
  assert.equal(r.value.lines[1].vatRate, 9);
  assert.equal(r.value.lines[2].vatRate, 0);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('lineTotal with single unit', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 6000 }), 6000);
});

test('invoiceTotals returns subtotal and total for single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 47500, total: 47500 });
});

test('invoiceTotals sums multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
      { qty: 10, unitPrice: 6000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500 + 120000 + 60000);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals handles empty invoice', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 0, total: 0 });
});

test('addLine adds a new line to a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const r2 = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(r2.value.lines[1].qty, 1);
});

test('addLine increases qty for an existing SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
